// mergeCustomers tests

test('mergeCustomers removes fromId and updates invoices', () => {
  const customers = [
    { id: 'C-001', name: 'Customer A', email: 'a@example.com', tier: 'standard' },
    { id: 'C-002', name: 'Customer B', email: 'b@example.com', tier: 'gold' },
  ];
  const invoices = [
    { number: 'INV-001', customerId: 'C-001' },
    { number: 'INV-002', customerId: 'C-001' },
    { number: 'INV-003', customerId: 'C-002' },
  ];

  const result = mergeCustomers(customers, invoices, 'C-001', 'C-002');
  assert.equal(result.ok, true);
  assert.equal(result.value.customers.length, 1);
  assert.equal(result.value.customers[0].id, 'C-002');
  assert.equal(result.value.invoices.length, 3);
  assert.equal(result.value.invoices[0].customerId, 'C-002');
  assert.equal(result.value.invoices[1].customerId, 'C-002');
  assert.equal(result.value.invoices[2].customerId, 'C-002');
});

test('mergeCustomers returns SAME_CUSTOMER if fromId equals intoId', () => {
  const customers = [
    { id: 'C-001', name: 'Customer A', email: 'a@example.com', tier: 'standard' },
  ];
  const invoices = [];

  const result = mergeCustomers(customers, invoices, 'C-001', 'C-001');
  assert.deepEqual(result, { ok: false, error: 'SAME_CUSTOMER' });
});

test('mergeCustomers returns SAME_CUSTOMER with case insensitive comparison', () => {
  const customers = [
    { id: 'C-001', name: 'Customer A', email: 'a@example.com', tier: 'standard' },
  ];
  const invoices = [];

  const result = mergeCustomers(customers, invoices, 'c-001', 'C-001');
  assert.deepEqual(result, { ok: false, error: 'SAME_CUSTOMER' });
});

test('mergeCustomers returns CUSTOMER_NOT_FOUND if fromId does not exist', () => {
  const customers = [
    { id: 'C-001', name: 'Customer A', email: 'a@example.com', tier: 'standard' },
